UPDATE inbox_message SET status='PROCESSED',result_type='INCIDENT',result_id=#{result},attempt_count=attempt_count+1,
  last_error_code=NULL,last_attempt_at=#{now},processed_at=#{now},lock_version=lock_version+1,
  updated_at=#{now},updated_by_type='SERVICE' WHERE tenant_id=#{tenantId} AND inbox_id=#{inboxId} AND status='RECOVERY_REQUIRED' AND lock_version=#{version}


UPDATE inbox_message SET status='REJECTED',result_type=NULL,result_id=NULL,attempt_count=attempt_count+1,
  last_error_code=#{error},last_attempt_at=#{now},processed_at=#{now},lock_version=lock_version+1,updated_at=#{now},updated_by_type='SERVICE'
WHERE tenant_id=#{tenantId} AND inbox_id=#{inboxId} AND status='RECOVERY_REQUIRED' AND lock_version=#{version}
